import{_ as o,o as t,c as r,a2 as a}from"./chunks/framework.BXzK3EA4.js";const h=JSON.parse('{"title":"Bare Metal Cloud Rescue Mode User Guide","description":"","frontmatter":{"title":"Bare Metal Cloud Rescue Mode User Guide"},"headers":[],"relativePath":"operations-knowledge-base/baremetal/bare-metal-cloud-rescue-mode-user-guide.md","filePath":"operations-knowledge-base/baremetal/bare-metal-cloud-rescue-mode-user-guide.md","lastUpdated":1794292919000}'),s={name:"operations-knowledge-base/baremetal/bare-metal-cloud-rescue-mode-user-guide.md"};function n(i,e,l,d,u,c){return t(),r("div",null,[...e[0]||(e[0]=[a('<h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>This document explains how to use the Rescue Mode feature through the Bare Metal Cloud Control Panel, including its applicable scenarios, configuration options, login methods, and important considerations. It is designed to help you perform system maintenance, troubleshooting, and data recovery when your server encounters issues.</p><p><strong>Applicable Product:</strong> Bare Metal Cloud</p><hr><h2 id="_1-what-is-rescue-mode" tabindex="-1">1. What is Rescue Mode? <a class="header-anchor" href="#_1-what-is-rescue-mode" aria-label="Permalink to &quot;1. What is Rescue Mode?&quot;">​</a></h2><p>Rescue Mode is a temporary maintenance environment that runs independently from your server&#39;s installed operating system.</p><p>When the operating system fails to boot, or you cannot access the server via SSH or Remote Desktop (RDP), Rescue Mode allows you to start the server in a separate environment for system maintenance, troubleshooting, and data recovery.</p><blockquote><p><strong>Note:</strong></p><p>Rescue Mode does <strong>not</strong> reinstall the operating system or format your disks. It provides a temporary maintenance environment for troubleshooting and recovery purposes.</p></blockquote><hr><h2 id="_2-when-should-i-use-rescue-mode" tabindex="-1">2. When Should I Use Rescue Mode? <a class="header-anchor" href="#_2-when-should-i-use-rescue-mode" aria-label="Permalink to &quot;2. When Should I Use Rescue Mode?&quot;">​</a></h2><p>Rescue Mode is recommended in the following situations:</p><ul><li>The operating system fails to boot.</li><li>Unable to connect via SSH (Linux).</li><li>Unable to connect via Remote Desktop (RDP) (Windows).</li><li>Incorrect system configuration prevents login.</li><li>System files or configuration need to be repaired.</li><li>Important data needs to be backed up or recovered.</li><li>Disk inspection or other system maintenance is required.</li></ul><hr><h2 id="_3-entering-rescue-mode" tabindex="-1">3. Entering Rescue Mode <a class="header-anchor" href="#_3-entering-rescue-mode" aria-label="Permalink to &quot;3. Entering Rescue Mode&quot;">​</a></h2><ol><li>Log in to the <strong>Raksmart Client Portal</strong>.</li><li>Navigate to <strong>Product Management</strong> → <strong>Bare Metal Cloud</strong>.</li><li>Select the server you want to manage.</li><li>Open the <strong>Management</strong> page.</li><li>Click <strong>Rescue</strong>.</li></ol><p>A Rescue configuration window will appear.</p><hr><h2 id="_4-configure-rescue-mode" tabindex="-1">4. Configure Rescue Mode <a class="header-anchor" href="#_4-configure-rescue-mode" aria-label="Permalink to &quot;4. Configure Rescue Mode&quot;">​</a></h2><h2 id="_1-select-the-rescue-system" tabindex="-1">1. Select the Rescue System <a class="header-anchor" href="#_1-select-the-rescue-system" aria-label="Permalink to &quot;1. Select the Rescue System&quot;">​</a></h2><p>Choose the appropriate Rescue system based on your maintenance requirements.</p><p>The following Rescue systems are currently available:</p><ul><li>Windows (Chinese)</li><li>Windows (English)</li><li>Linux</li></ul><p>Please select the Rescue system that best fits your maintenance needs.</p><hr><h2 id="_2-set-a-temporary-password" tabindex="-1">2. Set a Temporary Password <a class="header-anchor" href="#_2-set-a-temporary-password" aria-label="Permalink to &quot;2. Set a Temporary Password&quot;">​</a></h2><p>Before entering Rescue Mode, you must configure a temporary login password.</p><p>You may choose to:</p><ul><li>Use a system-generated random password.</li><li>Set your own custom password.</li></ul><blockquote><p><strong>Important:</strong></p><p><strong>Please save the temporary password carefully. It will only be displayed once and cannot be viewed again.</strong></p><p>It is recommended to copy or record the password before confirming the operation.</p></blockquote><hr><h2 id="_3-confirm-force-shutdown" tabindex="-1">3. Confirm Force Shutdown <a class="header-anchor" href="#_3-confirm-force-shutdown" aria-label="Permalink to &quot;3. Confirm Force Shutdown&quot;">​</a></h2><p>Before entering Rescue Mode, you must check the following option:</p><p>☑ <strong>I agree to perform a forced shutdown</strong></p><blockquote><p><strong>Note:</strong></p><p>Rescue Mode requires the server to reboot into a separate maintenance environment.</p><p>A forced shutdown will be performed. Please ensure that service interruption is acceptable before proceeding.</p></blockquote><hr><h2 id="_5-starting-rescue-mode" tabindex="-1">5. Starting Rescue Mode <a class="header-anchor" href="#_5-starting-rescue-mode" aria-label="Permalink to &quot;5. Starting Rescue Mode&quot;">​</a></h2><p>After confirming all settings, click <strong>Confirm</strong> to start Rescue Mode.</p><p>The system will automatically:</p><ul><li>Force shutdown the current server.</li><li>Boot into the selected Rescue environment.</li><li>Create a temporary login environment.</li></ul><p>Once Rescue Mode has started successfully, you can log in using the temporary password you configured.</p><hr><h2 id="_6-logging-in-to-rescue-mode" tabindex="-1">6. Logging in to Rescue Mode <a class="header-anchor" href="#_6-logging-in-to-rescue-mode" aria-label="Permalink to &quot;6. Logging in to Rescue Mode&quot;">​</a></h2><p>Rescue Mode supports network connectivity, allowing you to log in remotely or through the VNC console.</p><h2 id="linux-rescue" tabindex="-1">Linux Rescue <a class="header-anchor" href="#linux-rescue" aria-label="Permalink to &quot;Linux Rescue&quot;">​</a></h2><p>Supported login methods:</p><ul><li>SSH</li><li>VNC Console</li></ul><p>Default SSH port:</p><p><strong>22</strong></p><p>Use the username provided by the Rescue system and the temporary password configured when creating Rescue Mode.</p><hr><h2 id="windows-rescue" tabindex="-1">Windows Rescue <a class="header-anchor" href="#windows-rescue" aria-label="Permalink to &quot;Windows Rescue&quot;">​</a></h2><p>Supported login methods:</p><ul><li>Remote Desktop (RDP)</li><li>VNC Console</li></ul><p>Default Remote Desktop (RDP) port:</p><p><strong>3389</strong></p><p>Use the temporary password configured when creating Rescue Mode to log in.</p><hr><h2 id="_7-what-can-you-do-in-rescue-mode" tabindex="-1">7. What Can You Do in Rescue Mode? <a class="header-anchor" href="#_7-what-can-you-do-in-rescue-mode" aria-label="Permalink to &quot;7. What Can You Do in Rescue Mode?&quot;">​</a></h2><p>After entering Rescue Mode, you can perform the following maintenance tasks:</p><ul><li>Check system configuration.</li><li>Repair system files.</li><li>Check disk status.</li><li>Mount the system disk.</li><li>Mount additional data disks.</li><li>Back up or recover important data.</li><li>Modify system configuration files.</li><li>Troubleshoot system startup issues.</li><li>Perform other maintenance and recovery operations.</li></ul><blockquote><p><strong>Note:</strong></p><p>If your server has one or more additional data disks, they <strong>will not be mounted automatically</strong> in Rescue Mode. You must mount them manually before accessing the data.</p></blockquote><hr><h2 id="_8-exiting-rescue-mode" tabindex="-1">8. Exiting Rescue Mode <a class="header-anchor" href="#_8-exiting-rescue-mode" aria-label="Permalink to &quot;8. Exiting Rescue Mode&quot;">​</a></h2><blockquote><p>After completing your maintenance tasks, you can exit Rescue Mode through the control panel.</p><h3 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h3><ol><li>The <strong>Rescue</strong> button will now change to <strong>Exit Rescue</strong>.</li><li>Click <strong>Exit Rescue</strong>.</li></ol><p>The system will automatically:</p><ul><li>Exit Rescue Mode.</li><li>Reboot the server.</li><li>Boot back into the original operating system.</li></ul><blockquote><p><strong>Note:</strong></p><p>After clicking <strong>Exit Rescue</strong>, the server will reboot automatically. No additional manual restart is required.</p></blockquote></blockquote><hr><h2 id="_9-frequently-asked-questions" tabindex="-1">9. Frequently Asked Questions <a class="header-anchor" href="#_9-frequently-asked-questions" aria-label="Permalink to &quot;9. Frequently Asked Questions&quot;">​</a></h2><h3 id="q1-will-entering-rescue-mode-delete-my-server-data" tabindex="-1">Q1: Will entering Rescue Mode delete my server data? <a class="header-anchor" href="#q1-will-entering-rescue-mode-delete-my-server-data" aria-label="Permalink to &quot;Q1: Will entering Rescue Mode delete my server data?&quot;">​</a></h3><p>No.</p><p>Rescue Mode does not reinstall the operating system, format disks, or delete any server data.</p><hr><h3 id="q2-why-is-a-forced-shutdown-required" tabindex="-1">Q2: Why is a forced shutdown required? <a class="header-anchor" href="#q2-why-is-a-forced-shutdown-required" aria-label="Permalink to &quot;Q2: Why is a forced shutdown required?&quot;">​</a></h3><p>Rescue Mode runs in an independent maintenance environment.</p><p>The server must reboot into this environment, so a forced shutdown is required.</p><hr><h3 id="q3-can-i-view-the-temporary-password-again-later" tabindex="-1">Q3: Can I view the temporary password again later? <a class="header-anchor" href="#q3-can-i-view-the-temporary-password-again-later" aria-label="Permalink to &quot;Q3: Can I view the temporary password again later?&quot;">​</a></h3><p>No.</p><p>The temporary password is displayed only once when Rescue Mode is created.</p><p>Please copy or record it before proceeding. If the password is lost, you will need to recreate Rescue Mode and set a new temporary password.</p><hr><h3 id="q4-what-login-methods-are-supported-in-rescue-mode" tabindex="-1">Q4: What login methods are supported in Rescue Mode? <a class="header-anchor" href="#q4-what-login-methods-are-supported-in-rescue-mode" aria-label="Permalink to &quot;Q4: What login methods are supported in Rescue Mode?&quot;">​</a></h3><p>The following login methods are supported:</p><p><strong>Linux Rescue</strong></p><ul><li>SSH (Default Port: <strong>22</strong>)</li><li>VNC Console</li></ul><p><strong>Windows Rescue</strong></p><ul><li>Remote Desktop (RDP) (Default Port: <strong>3389</strong>)</li><li>VNC Console</li></ul><p>Please use the temporary password configured when creating Rescue Mode.</p><hr><h3 id="q5-why-can-t-i-see-my-data-disk-after-entering-rescue-mode" tabindex="-1">Q5: Why can&#39;t I see my data disk after entering Rescue Mode? <a class="header-anchor" href="#q5-why-can-t-i-see-my-data-disk-after-entering-rescue-mode" aria-label="Permalink to &quot;Q5: Why can&#39;t I see my data disk after entering Rescue Mode?&quot;">​</a></h3><p>Additional data disks are <strong>not mounted automatically</strong>.</p><p>Please manually mount the data disk after logging into Rescue Mode before accessing your data.</p><hr><h3 id="q6-how-do-i-return-to-my-original-operating-system" tabindex="-1">Q6: How do I return to my original operating system? <a class="header-anchor" href="#q6-how-do-i-return-to-my-original-operating-system" aria-label="Permalink to &quot;Q6: How do I return to my original operating system?&quot;">​</a></h3><p>After completing your maintenance tasks, click <strong>Exit Rescue</strong> in the control panel.</p><p>The system will automatically exit Rescue Mode, reboot the server, and boot back into the original operating system.</p><p>No additional manual reboot is required.</p><p>Q7: Does Rescue Mode support network connectivity?</p><p>Yes.</p><p>Rescue Mode supports network access by default.</p><p>You can connect remotely using:</p><ul><li>SSH (Linux)</li><li>Remote Desktop (RDP) (Windows)</li><li>VNC Console</li></ul><hr><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><p>⚠️ Before entering Rescue Mode, ensure that service interruption is acceptable, as the server will be forcibly shut down.</p><p>⚠️ The temporary password is displayed only once. Please save it before proceeding.</p><p>⚠️ Rescue Mode does not reinstall the operating system or delete any server data.</p><p>⚠️ Rescue Mode supports network connectivity and can be accessed via SSH, Remote Desktop (RDP), or the VNC Console.</p><p>⚠️ The default SSH port for Linux Rescue is <strong>22</strong>, and the default Remote Desktop (RDP) port for Windows Rescue is <strong>3389</strong>.</p><p>⚠️ Additional data disks are not mounted automatically in Rescue Mode and must be mounted manually.</p><p>⚠️ After completing maintenance, be sure to exit Rescue Mode before restarting the server.</p><hr>',110)])])}const m=o(s,[["render",n]]);export{h as __pageData,m as default};
